        <div class="stats three"><article><div class="stat-top">Physical potable stock<Boxes :size="19" /></div><strong>{{ w.fmt(w.activeResources.reduce((sum, resource) => sum + resource.liters, 0)) }} <small>L</small></strong><span>Actual recorded stock at active sources</span></article><article><div class="stat-top">Reserved for delivery<Truck :size="19" /></div><strong>{{ w.fmt(w.committed(w.s)) }} <small>L</small></strong><span>Active allocations awaiting reconciliation</span></article><article><div class="stat-top">Available to allocate<Droplets :size="19" /></div><strong>{{ w.fmt(w.available(w.s)) }} <small>L</small></strong><span>Physical stock minus reservations</span></article></div>
        <article class="card"><div class="card-heading"><div><h3>Potable water sources</h3><p>Update physical quantities when a supply is received or an inventory count is completed.</p></div><button type="button" class="primary" :disabled="w.disabled" @click="w.openResource()"><Plus :size="16" /> Add source</button></div><div v-if="w.s.resources.length" class="table-scroll"><table><thead><tr><th>SOURCE</th><th>PHYSICAL STOCK</th><th>RESERVED</th><th>AVAILABLE</th><th>UPDATED</th><th></th></tr></thead><tbody><tr v-for="resource in w.s.resources" :key="resource.id"><td><b>{{ resource.name }}</b><small>{{ resource.active ? 'Active source' : 'Archived' }}</small><small v-if="resource.notes">{{ resource.notes }}</small></td><td>{{ w.fmt(resource.liters) }} L</td><td>{{ w.fmt(w.committed(w.s, resource.id)) }} L</td><td>{{ w.fmt(Math.max(0, resource.liters - w.committed(w.s, resource.id))) }} L</td><td>{{ w.prettyDate(resource.updated) }}</td><td><button v-if="resource.active" type="button" class="text-button" :disabled="w.disabled" @click="w.openResource(resource)"><Pencil :size="14" /> Update stock</button></td></tr></tbody></table></div><EmptyState v-else title="No potable stock recorded" description="Add an actual supply source and its measured liters. The allocation engine can reserve only recorded, uncommitted stock." action="Add a supply source" :disabled="w.disabled" @action="w.openResource()" /></article>
        <article class="card"><div class="card-heading"><div><h3>Delivery teams &amp; vehicles</h3><p>Teams appear in the profile selector and can receive scheduled assignments.</p></div><button type="button" class="primary" :disabled="w.disabled" @click="w.openTeam()"><Plus :size="16" /> Add team</button></div><div v-if="w.s.teams.length" class="table-scroll"><table><thead><tr><th>TEAM</th><th>VEHICLE</th><th>CAPACITY / TRIP</th><th>ACTIVE TASKS</th><th>STATUS</th><th></th></tr></thead><tbody><tr v-for="team in w.s.teams" :key="team.id"><td><b>{{ team.name }}</b></td><td>{{ team.vehicle }}</td><td>{{ w.fmt(team.capacity) }} L</td><td>{{ w.s.deliveries.filter(delivery => delivery.teamId === team.id && w.active(delivery)).length }}</td><td><span :class="['badge', team.active ? 'teal' : 'neutral']">{{ team.active ? 'Available for assignment' : 'Inactive' }}</span></td><td><button type="button" class="text-button" :disabled="w.disabled" @click="w.openTeam(team)"><Pencil :size="14" /> Edit team</button></td></tr></tbody></table></div><EmptyState v-else title="No delivery teams yet" description="Register a real operating team, vehicle identifier, and potable-water capacity before assigning deliveries." action="Add a delivery team" :disabled="w.disabled" @action="w.openTeam()" /></article>
      </template>

      <template v-else-if="w.page === 'deliveries'">
        <div class="info-strip"><Truck :size="18" /><span>{{ w.barangay ? `Assistance for ${w.store.community}. Confirm what your barangay actually receives after a trip is finalized.` : w.coordinator ? 'Split large allocations into trips, assign teams, and track reconciliation and barangay receipts.' : w.selectedTeam ? `Assignments for ${w.selectedTeam.name}. Start the trip before recording its actual outcome.` : 'Choose your delivery team from your profile to view assignments.' }}</span></div>
        <div class="toolbar"><label class="search"><Search :size="17" /><input v-model="w.deliverySearch" placeholder="Search barangay, team, vehicle, or trip…" aria-label="Search delivery operations"></label><select v-model="w.deliveryFilter" aria-label="Filter delivery status"><option>All statuses</option><option v-for="status in w.deliveryStatuses" :key="status">{{ status }}</option></select></div>
        <div v-if="w.filteredDeliveries.length" class="community-cards"><article v-for="delivery in w.filteredDeliveries" :key="delivery.id" class="card padded delivery-card"><div class="card-heading"><span :class="['badge', w.statusClass(delivery.status)]">{{ delivery.status }}</span><Truck :size="21" /></div><h3>{{ w.reportName(delivery.reportId) }}</h3><small>Trip {{ w.shortId(delivery.id) }}</small><div class="delivery-liters">{{ w.fmt(delivery.liters) }} <small>L potable water allocated</small></div><p>{{ delivery.person || 'Awaiting team assignment' }}<br>{{ delivery.vehicle || 'No vehicle assigned' }} · {{ w.prettyDate(delivery.scheduled) }}</p><p v-if="['Completed','Partially Delivered','Failed'].includes(delivery.status)">Confirmed delivery: <b>{{ w.fmt(delivery.actual) }} L</b><br>{{ w.prettyDate(delivery.completed, true) }}</p><p v-if="delivery.notes">{{ delivery.notes }}</p><div v-if="delivery.receipt" :class="['receipt-flag', {'receipt-discrepancy': delivery.receipt.liters !== delivery.actual}]">Barangay receipt: {{ w.fmt(delivery.receipt.liters) }} L<span v-if="delivery.receipt.liters !== delivery.actual"> · {{ w.fmt(Math.abs(delivery.actual - delivery.receipt.liters)) }} L discrepancy to review</span></div><div v-else-if="['Completed','Partially Delivered'].includes(delivery.status)" class="receipt-flag">Awaiting barangay receipt</div><button type="button" class="secondary" @click="w.openDelivery(delivery)">{{ w.barangay && !delivery.receipt && delivery.actual ? 'Confirm receipt' : 'Open delivery' }} <ArrowRight :size="15" /></button></article></div>
        <EmptyState v-else :title="w.visibleDeliveries.length ? 'No deliveries match these filters' : 'No delivery tasks to show'" :description="w.barangay ? 'Approved assistance and its delivery progress will appear for your barangay here.' : w.personnel ? 'Assigned trips appear here for the team selected in your profile.' : 'Approve an allocation to create pending tasks. Record supplies and teams in Water resources before dispatch.'" />
      </template>

      <template v-else-if="w.page === 'analytics'">
        <div class="toolbar filter-dates"><label>Planning period from<input v-model="w.fromDate" type="date" aria-label="Analytics planning date from"></label><label>To<input v-model="w.toDate" type="date" :min="w.fromDate || undefined" aria-label="Analytics planning date to"></label><button type="button" class="secondary" @click="w.fromDate='';w.toDate=''">All dates</button><button type="button" class="primary" :disabled="w.invalidDateRange || !w.analyticsReports.length" @click="w.exportReports"><Download :size="16" /> Export requests</button><button type="button" class="secondary" :disabled="w.invalidDateRange || !w.analyticsDeliveries.length" @click="w.exportDeliveries">Export deliveries</button></div>
        <p v-if="w.invalidDateRange" class="form-error" role="alert">Choose an end date on or after the start date.</p>
        <div class="stats"><article><div class="stat-top">Verified unmet need<Droplets :size="19" /></div><strong>{{ w.fmt(w.analyticsNeed) }} <small>L</small></strong><span>Requests overlapping the selected dates</span></article><article><div class="stat-top">Active commitments<Boxes :size="19" /></div><strong>{{ w.fmt(w.analyticsCommitted) }} <small>L</small></strong><span>Stock reserved for selected requests</span></article><article><div class="stat-top">Potable water delivered<Truck :size="19" /></div><strong>{{ w.fmt(w.analyticsActual) }} <small>L</small></strong><span>Actual quantities recorded by delivery teams</span></article><article><div class="stat-top">Full-trip completion<Check :size="19" /></div><strong>{{ w.completionRate }}<small>%</small></strong><span>Completed ÷ finalized trips; excludes cancellations</span></article></div>
        <div class="dashboard-grid"><article class="card"><div class="card-heading"><div><h3>Requests by status</h3><p>Requests overlapping the selected planning period</p></div></div><BarChart first-label="Requests" unit="" :labels="w.reportStatuses" :values="w.reportStatuses.map(status => w.analyticsReports.filter(report => report.status === status).length)" /></article><article class="card"><div class="card-heading"><div><h3>Potable water response quantities</h3><p>Liters for selected requests</p></div></div><BarChart first-label="Potable water" unit="L" :labels="['Unmet need','Reserved','Delivered']" :values="[w.analyticsNeed,w.analyticsCommitted,w.analyticsActual]" /></article></div>
        <p class="scope-note">Totals cover the complete assistance periods of requests that overlap the selected dates. They are not daily-prorated delivery totals.</p><article class="card"><div class="card-heading"><div><h3>Allocation &amp; delivery history</h3><p>Reported quantities and independent barangay receipts</p></div></div><div v-if="w.analyticsDeliveries.length" class="table-scroll"><table><thead><tr><th>BARANGAY / TRIP</th><th>ALLOCATED</th><th>DELIVERED</th><th>STATUS</th><th>BARANGAY RECEIPT</th><th></th></tr></thead><tbody><tr v-for="delivery in w.analyticsDeliveries" :key="delivery.id"><td><b>{{ w.reportName(delivery.reportId) }}</b><small>{{ w.shortId(delivery.id) }}</small></td><td>{{ w.fmt(delivery.liters) }} L</td><td>{{ w.fmt(delivery.actual) }} L</td><td><span :class="['badge',w.statusClass(delivery.status)]">{{ delivery.status }}</span></td><td>{{ delivery.receipt ? w.fmt(delivery.receipt.liters) + ' L' : 'Not confirmed' }}<small v-if="delivery.receipt && delivery.receipt.liters !== delivery.actual">Discrepancy recorded</small></td><td><button type="button" class="text-button" @click="w.openDelivery(delivery)">Details <ArrowUpRight :size="14" /></button></td></tr></tbody></table></div><EmptyState v-else title="No delivery history in this period" description="Approved allocations and finalized delivery outcomes appear as operations progress." /></article>
        <article class="card padded"><div class="card-heading"><div><h3>Decision &amp; operation history</h3><p>Full operation history, with timestamps and the selected workspace context</p></div><button type="button" class="secondary" :disabled="!w.scopedAudit.length" @click="w.exportAudit"><Download :size="15" /> Audit CSV</button></div><div v-if="w.scopedAudit.length"><div v-for="(entry,index) in w.scopedAudit" :key="entry.id || index" class="audit-row"><span class="audit-dot" /><div><b>{{ entry.action }}</b><small>{{ entry.actor }}{{ entry.community ? ' · '+entry.community : '' }} · {{ w.prettyDate(entry.date,true) }}</small></div></div></div><EmptyState v-else title="No recorded operations yet" description="Saving a request, decision, stock change, allocation, or delivery creates a dated history entry." /></article>
      </template>

      <template v-else-if="w.page === 'communities'">
        <div class="info-strip"><Info :size="18" /><span>Official census figures are reference context. They are not live shortage counts or automatic demand requests.</span></div>
        <div class="stats three directory-summary"><article><span>Barangays in Calapan</span><strong>{{ w.s.barangays.length }}</strong></article><article><span>2024 total population</span><strong>{{ w.fmt(w.totalPopulation) }}</strong></article><article><span>2024 households</span><strong>{{ w.fmt(w.totalHouseholds) }}</strong></article></div>
        <div class="toolbar"><label class="search"><Search :size="17" /><input v-model="w.directorySearch" placeholder="Search barangay or PSGC code…" aria-label="Search barangay directory"></label></div>
        <article class="card"><div class="card-heading"><div><h3>Calapan barangay reference</h3><p>{{ w.directory.length }} records · reference date {{ w.s.barangays[0]?.referenceDate || 'loading' }}</p></div><a v-if="w.s.barangays[0]?.sourceUrl" class="small-link" :href="w.s.barangays[0].sourceUrl" target="_blank" rel="noreferrer">Official source <ArrowUpRight :size="14" /></a></div><div v-if="w.directory.length" class="table-scroll"><table><thead><tr><th>BARANGAY / PSGC</th><th>TOTAL POPULATION</th><th>HOUSEHOLD POPULATION</th><th>HOUSEHOLDS</th><th>REFERENCE LOCATION</th><th>SOURCE</th></tr></thead><tbody><tr v-for="community in w.directory" :key="community.id" :class="{'selected-community-row':w.barangay && community.name === w.store.community}"><td><b>{{ community.name }}</b><small>{{ community.psgc }}{{ w.barangay && community.name === w.store.community ? ' · Your barangay' : '' }}</small></td><td>{{ w.fmt(community.population) }}</td><td>{{ w.fmt(community.householdPopulation) }}</td><td>{{ w.fmt(community.households) }}</td><td><template v-if="community.lat !== null && community.lng !== null">{{ community.lat.toFixed(5) }}, {{ community.lng.toFixed(5) }}<small>{{ community.coordinateAccuracy || 'Reference point, not a service-area boundary' }}</small></template><template v-else>Not available<small>Record a verified location when reporting</small></template></td><td><a class="small-link" :href="community.sourceUrl" target="_blank" rel="noreferrer">PSA source <ArrowUpRight :size="12" /></a><small>{{ community.referenceDate }}</small></td></tr></tbody></table></div><EmptyState v-else title="No reference record matches" description="Search using a barangay name or its official PSGC code." /></article>
      </template>
    </template>
    <article v-else class="card padded"><h2>{{ w.page === 'dashboard' ? 'Select your workspace' : 'This page is outside your selected workspace' }}</h2><p>Use your profile to select a role. Barangay representatives and delivery personnel have tools specific to their community or team.</p><RouterLink class="primary" to="/dashboard">Return to your dashboard <ArrowRight :size="16" /></RouterLink></article>
  </section>

  <WorkspaceModal v-if="w.showReportForm" :title="w.editingId ? 'Update potable water request' : 'Request potable water assistance'" wide :busy="w.store.saving" @close="w.showReportForm=false">
    <template #subtitle><p>{{ w.store.community }} · Calapan City, Oriental Mindoro</p></template>
    <form @submit.prevent="w.submitReport">
      <div class="info-strip scope-note"><Info :size="17" /><span>Include water for <b>drinking and food preparation</b>. Exclude bathing, laundry, and irrigation. Enter actual affected people, not the whole census population unless everyone is affected.</span></div>
      <p v-if="w.reference" class="muted">2024 reference: {{ w.fmt(w.reference.population) }} people and {{ w.fmt(w.reference.households) }} households. This reference does not fill in affected counts.</p>
      <div class="form-grid"><label>Affected households<input v-model.number="w.reportForm.households" type="number" min="1" step="1" required :disabled="w.disabled"></label><label>Affected people<input v-model.number="w.reportForm.population" type="number" min="1" step="1" required :disabled="w.disabled"></label><label>Local potable supply (L / day)<input v-model.number="w.reportForm.local" type="number" min="0" step="1" required :disabled="w.disabled"></label><label>Days shortage has been observed<input v-model.number="w.reportForm.days" type="number" min="1" max="365" step="1" required :disabled="w.disabled"></label><label>Assistance planning start<input v-model="w.reportForm.planningDate" type="date" required :disabled="w.disabled"></label><label>Days of assistance requested<input v-model.number="w.reportForm.planningDays" type="number" min="1" max="14" step="1" required :disabled="w.disabled"></label></div>
      <div class="formula">Planning basis: {{ w.s.drinkingBaseline }} L drinking + {{ w.s.cookingBaseline }} L food preparation = {{ w.s.baseline }} L per affected person per day. Current request’s net need before assistance: {{ w.fmt(w.formNeed) }} L.</div>
      <p class="muted">Allowances are configurable planning estimates. Local circumstances may require a different response.</p>
      <div class="form-grid two"><label>Reported latitude (optional)<input v-model.number="w.reportForm.lat" type="number" min="-90" max="90" step="any" :disabled="w.disabled"></label><label>Reported longitude (optional)<input v-model.number="w.reportForm.lng" type="number" min="-180" max="180" step="any" :disabled="w.disabled"></label></div><p class="muted">A barangay reference point is used when available. Update it only with a verified shortage location; leave both coordinates blank if unknown.</p>
      <label class="checkbox"><input v-model="w.reportForm.urgency" type="checkbox" :disabled="w.disabled"> Elevated urgency: immediate drinking or food-preparation access disruption</label>
      <label>Situation and response needs<textarea v-model="w.reportForm.description" minlength="10" maxlength="2000" required :disabled="w.disabled" placeholder="Describe the cause, affected area, available potable sources, and immediate needs. Use aggregate information; do not include residents’ names or contact details." /></label>
      <p v-if="w.formError" class="form-error" role="alert">{{ w.formError }}</p>
      <div class="form-actions"><button type="button" class="secondary" :disabled="w.store.saving" @click="w.showReportForm=false">Cancel</button><button class="primary" :disabled="w.disabled"><ClipboardCheck :size="16" /> {{ w.store.saving ? 'Saving request…' : w.editingId ? 'Save & resubmit for review' : 'Submit for review' }}</button></div>
    </form>
  </WorkspaceModal>

  <WorkspaceModal v-if="w.detail" :title="w.detail.barangay + ' request'" wide :busy="w.store.saving" @close="w.detailId=''">
    <template #subtitle><p>Request {{ w.shortId(w.detail.id) }} · {{ w.prettyDate(w.detail.date) }}</p></template>
    <span :class="['badge',w.statusClass(w.detail.status)]">{{ w.detail.status }}</span>
    <div class="detail-grid"><div><small>AFFECTED PEOPLE</small><strong>{{ w.fmt(w.detail.population) }}</strong></div><div><small>AFFECTED HOUSEHOLDS</small><strong>{{ w.fmt(w.detail.households) }}</strong></div><div><small>LOCAL POTABLE WATER / DAY</small><strong>{{ w.fmt(w.detail.local) }} L</strong></div><div><small>ASSISTANCE PLANNING PERIOD</small><strong>{{ w.detail.planningDays }} day{{ w.detail.planningDays === 1 ? '' : 's' }}</strong><small>From {{ w.prettyDate(w.detail.planningDate) }}</small></div><div><small>REMAINING UNMET NEED</small><strong>{{ w.fmt(w.unmet(w.s,w.detail)) }} L</strong></div><div><small>ACTIVE COMMITMENTS</small><strong>{{ w.fmt(w.reportCommitted(w.detail.id)) }} L</strong></div></div>
    <p class="situation-text">{{ w.detail.description }}</p><p><b>{{ w.detail.urgency ? 'Elevated urgency reported' : 'Standard urgency' }}</b> · Shortage observed for {{ w.detail.days }} day{{ w.detail.days === 1 ? '' : 's' }}.</p><p v-if="w.detail.lat !== null && w.detail.lng !== null">Reported/reference location: {{ w.detail.lat.toFixed(5) }}, {{ w.detail.lng.toFixed(5) }}</p><p v-if="w.detail.reason" class="review-note"><b>Review note:</b> {{ w.detail.reason }}</p>
    <div class="workflow-steps"><span>Submitted</span><span>{{ ['Verified','Resolved'].includes(w.detail.status) ? 'Reviewed' : 'Awaiting / updating review' }}</span><span>{{ w.reportCommitted(w.detail.id) > 0 ? 'Water reserved' : 'No active reservation' }}</span><span>{{ w.fmt(w.reportActual(w.detail.id)) }} L delivered</span></div>
    <div v-if="w.s.deliveries.some(delivery=>delivery.reportId===w.detail?.id)" class="request-list"><h3>Deliveries for this request</h3><div v-for="delivery in w.s.deliveries.filter(item=>item.reportId===w.detail?.id)" :key="delivery.id" class="request-item"><div class="request-item-heading"><span>{{ w.fmt(delivery.liters) }} L · {{ delivery.status }}</span><button type="button" class="text-button" @click="w.detailId='';w.openDelivery(delivery)">View trip <ArrowUpRight :size="14" /></button></div><small>{{ delivery.person || 'No team assigned' }} · {{ w.prettyDate(delivery.scheduled) }}</small></div></div>
    <template v-if="w.barangay && ['Pending','Correction requested'].includes(w.detail.status)"><div class="button-row"><button type="button" class="primary" :disabled="w.disabled" @click="w.editReport(w.detail)"><Pencil :size="16" /> Edit &amp; resubmit</button></div><hr><label>Reason to withdraw this request<textarea v-model="w.decisionReason" placeholder="Explain why assistance is no longer requested" :disabled="w.disabled" /></label><button type="button" class="danger" :disabled="w.disabled || !w.decisionReason.trim()" @click="w.closeReport('report.withdraw')">Withdraw request</button></template>
    <template v-if="w.coordinator && ['Pending','Correction requested'].includes(w.detail.status)"><hr><label>Review explanation<textarea v-model="w.decisionReason" placeholder="Record what was verified or what needs correction" :disabled="w.disabled" /></label><div class="button-row"><button type="button" class="primary" :disabled="w.disabled || !w.decisionReason.trim()" @click="w.review('Verified')"><Check :size="16" /> Verify request</button><button type="button" class="secondary" :disabled="w.disabled || !w.decisionReason.trim()" @click="w.review('Correction requested')">Request correction</button><button type="button" class="danger" :disabled="w.disabled || !w.decisionReason.trim()" @click="w.review('Rejected')">Reject request</button></div></template>
    <template v-if="w.coordinator && w.detail.status === 'Verified'"><hr><label>Resolution note<textarea v-model="w.decisionReason" placeholder="Confirm how the shortage was resolved or why the request can be closed" :disabled="w.disabled" /></label><button type="button" class="secondary" :disabled="w.disabled || !w.decisionReason.trim() || w.reportCommitted(w.detail.id)>0" @click="w.closeReport('report.resolve')">Mark request resolved</button><p v-if="w.reportCommitted(w.detail.id)>0" class="muted">Finalize or cancel active delivery commitments before resolving this request.</p></template>
    <p v-if="w.formError" class="form-error" role="alert">{{ w.formError }}</p>
  </WorkspaceModal>

  <WorkspaceModal v-if="w.showResource" :title="w.resourceId ? 'Update potable water stock' : 'Add a potable water source'" :busy="w.store.saving" @close="w.showResource=false">
    <form @submit.prevent="w.saveResource"><p>For drinking and food preparation only. Enter the actual physical stock, including any reserved liters.</p><label>Supply source / storage location<input v-model="w.resourceForm.name" maxlength="120" required :disabled="w.disabled"></label><label>Physical potable stock (liters)<input v-model.number="w.resourceForm.liters" type="number" :min="w.resourceId?w.committed(w.s,w.resourceId):0" step="1" required :disabled="w.disabled"></label><p v-if="w.resourceId" class="muted">{{ w.fmt(w.committed(w.s,w.resourceId)) }} L are reserved. Stock cannot be recorded below this amount.</p><label>Stock record / count note<textarea v-model="w.resourceForm.notes" maxlength="1000" placeholder="Source, replenishment or stock-count context" :disabled="w.disabled" /></label><p v-if="w.formError" class="form-error" role="alert">{{ w.formError }}</p><div class="form-actions"><button type="button" class="secondary" :disabled="w.store.saving" @click="w.showResource=false">Cancel</button><button class="primary" :disabled="w.disabled">{{ w.store.saving?'Saving…':'Save potable stock' }}</button></div></form><template v-if="w.resourceId"><hr><button type="button" class="danger" :disabled="w.disabled || !!w.editingResource?.liters || w.committed(w.s,w.resourceId)>0" @click="w.archiveResource">Archive empty supply source</button><p class="muted">A source can be archived after its stock and active reservations reach zero. Its history remains available.</p></template>
  </WorkspaceModal>

  <WorkspaceModal v-if="w.showTeam" :title="w.editingTeamId ? 'Edit delivery team' : 'Add a delivery team'" :busy="w.store.saving" @close="w.showTeam=false">
    <form @submit.prevent="w.saveTeam"><label>Team name<input v-model="w.teamForm.name" maxlength="120" required :disabled="w.disabled" placeholder="Use an operating team name"></label><label>Vehicle identifier<input v-model="w.teamForm.vehicle" maxlength="80" required :disabled="w.disabled"></label><label>Potable-water capacity per trip (liters)<input v-model.number="w.teamForm.capacity" type="number" min="1" step="1" required :disabled="w.disabled"></label><label class="checkbox"><input v-model="w.teamForm.active" type="checkbox" :disabled="w.disabled"> Available for new assignments</label><p class="muted">Use the vehicle’s actual potable-water carrying capacity. Existing active assignments must be completed or cancelled before a team is made inactive.</p><p v-if="w.formError" class="form-error" role="alert">{{ w.formError }}</p><div class="form-actions"><button type="button" class="secondary" :disabled="w.store.saving" @click="w.showTeam=false">Cancel</button><button class="primary" :disabled="w.disabled">{{ w.store.saving?'Saving…':'Save delivery team' }}</button></div></form>
  </WorkspaceModal>

  <WorkspaceModal v-if="w.deliveryDetail" :title="w.reportName(w.deliveryDetail.reportId) + ' delivery'" :busy="w.store.saving" @close="w.deliveryId=''">
    <template #subtitle><p>Trip {{ w.shortId(w.deliveryDetail.id) }} · {{ w.fmt(w.deliveryDetail.liters) }} L potable water</p></template>
    <span :class="['badge',w.statusClass(w.deliveryDetail.status)]">{{ w.deliveryDetail.status }}</span><p>{{ w.deliveryDetail.person || 'No team assigned' }} · {{ w.deliveryDetail.vehicle || 'No vehicle assigned' }}<br>Scheduled: {{ w.prettyDate(w.deliveryDetail.scheduled) }}</p>
    <template v-if="w.coordinator && ['Pending','Assigned'].includes(w.deliveryDetail.status)">
      <form @submit.prevent="w.assignDelivery"><h3>{{ w.deliveryDetail.status==='Assigned' ? 'Update delivery assignment' : 'Assign this delivery' }}</h3><p>Choose the operating team, vehicle, and schedule for this trip.</p><label>Assign to a delivery team<select v-model="w.task.teamId" required @change="w.assignmentTeamChanged" :disabled="w.disabled"><option value="" disabled>Select an active team</option><option v-for="team in w.activeTeams" :key="team.id" :value="team.id">{{ team.name }} · {{ w.fmt(team.capacity) }} L / trip</option></select></label><p v-if="!w.activeTeams.length" class="muted">Create an active team in Water resources before assigning this trip.</p><label>Vehicle identifier<input v-model="w.task.vehicle" required maxlength="80" :disabled="w.disabled"></label><label>Scheduled delivery date<input v-model="w.task.scheduled" type="date" required :disabled="w.disabled"></label><p v-if="w.assignmentTeam && w.deliveryDetail.liters > w.assignmentTeam.capacity" class="form-error">This allocation exceeds the selected vehicle’s {{ w.fmt(w.assignmentTeam.capacity) }} L capacity. Split it into smaller trips below.</p><button class="primary" :disabled="w.disabled || !w.task.teamId || !!(w.assignmentTeam && w.deliveryDetail.liters > w.assignmentTeam.capacity)">{{ w.deliveryDetail.status==='Assigned' ? 'Save assignment changes' : 'Assign delivery' }}</button></form>
      <template v-if="w.deliveryDetail.status==='Pending'"><hr><form @submit.prevent="w.splitDelivery"><h3>Split a large allocation into trips</h3><p>Keep the same total reservation while creating vehicle-sized tasks, up to 50 trips.</p><label>Maximum potable liters per trip<input v-model.number="w.task.splitLiters" type="number" min="1" :max="w.deliveryDetail.liters-1" step="1" required :disabled="w.disabled"></label><p v-if="w.task.splitLiters>0" class="muted">{{ Math.ceil(w.deliveryDetail.liters/w.task.splitLiters) }} trip{{ Math.ceil(w.deliveryDetail.liters/w.task.splitLiters)===1?'':'s' }} for {{ w.fmt(w.deliveryDetail.liters) }} L total.</p><button class="secondary" :disabled="w.disabled || !w.task.splitLiters || w.task.splitLiters>=w.deliveryDetail.liters || Math.ceil(w.deliveryDetail.liters/w.task.splitLiters)>50">Split pending allocation</button></form></template>
    </template>
    <template v-if="w.personnel && w.deliveryDetail.status === 'Assigned'"><div class="info-strip"><Truck :size="18" /><span>Start only when your team departs with the assigned potable water.</span></div><button type="button" class="primary" :disabled="w.disabled" @click="w.startDelivery">Start trip · In transit <ArrowRight :size="16" /></button></template>
    <template v-if="w.personnel && w.deliveryDetail.status === 'In Transit'"><form @submit.prevent="w.confirmDelivery"><label>Delivery outcome<select v-model="w.task.status" :disabled="w.disabled"><option>Completed</option><option :disabled="w.deliveryDetail.liters<=1">Partially Delivered</option><option>Failed</option></select></label><label>Actual potable liters delivered<input v-model.number="w.task.actual" type="number" :min="w.task.status==='Partially Delivered' ? 1 : 0" :max="w.task.status==='Partially Delivered' ? w.deliveryDetail.liters-1 : w.deliveryDetail.liters" step="1" required :disabled="w.disabled || w.task.status!=='Partially Delivered'"></label><p class="muted">Completed requires the full assigned quantity. Record less as a partial delivery, or zero as a failed trip.</p><label>Delivery outcome notes<textarea v-model="w.task.notes" maxlength="2000" :required="w.task.status!=='Completed'" :disabled="w.disabled" placeholder="Explain any shortfall, incident, or failed delivery" /></label><button class="primary" :disabled="w.disabled">Confirm outcome &amp; reconcile stock</button></form></template>
    <template v-if="['Completed','Partially Delivered','Failed'].includes(w.deliveryDetail.status)"><div class="detail-grid"><div><small>RECORDED DELIVERED</small><strong>{{ w.fmt(w.deliveryDetail.actual) }} L</strong></div><div><small>FINALIZED</small><strong class="detail-date">{{ w.prettyDate(w.deliveryDetail.completed,true) }}</strong></div></div><p v-if="w.deliveryDetail.notes">{{ w.deliveryDetail.notes }}</p><template v-if="w.deliveryDetail.receipt"><div :class="['info-strip',{'warning-strip':w.deliveryDetail.receipt.liters!==w.deliveryDetail.actual}]"><ClipboardCheck :size="18" /><span>Barangay confirmed {{ w.fmt(w.deliveryDetail.receipt.liters) }} L on {{ w.prettyDate(w.deliveryDetail.receipt.confirmedAt,true) }}.<template v-if="w.deliveryDetail.receipt.liters!==w.deliveryDetail.actual"> {{ w.fmt(Math.abs(w.deliveryDetail.actual-w.deliveryDetail.receipt.liters)) }} L discrepancy recorded for coordinator follow-up.</template></span></div><p v-if="w.deliveryDetail.receipt.notes">Receipt note: {{ w.deliveryDetail.receipt.notes }}</p></template><form v-else-if="w.barangay && w.deliveryDetail.actual>0" @submit.prevent="w.receiveDelivery"><hr><h3>Confirm your barangay’s receipt</h3><p>Record the quantity actually received, up to the assigned trip quantity. Both under- and over-receipt differences are kept for coordinator follow-up and do not rewrite the delivery team’s record.</p><label>Potable liters received<input v-model.number="w.task.receiptLiters" type="number" min="0" :max="w.deliveryDetail.liters" step="1" required :disabled="w.disabled"></label><label>Receipt / discrepancy note<textarea v-model="w.task.receiptNotes" maxlength="2000" :required="w.task.receiptLiters!==w.deliveryDetail.actual" :disabled="w.disabled" placeholder="Explain any difference from the delivery record" /></label><button class="primary" :disabled="w.disabled">Confirm barangay receipt</button></form><p v-else-if="w.deliveryDetail.actual>0" class="muted">Awaiting the barangay representative’s receipt confirmation.</p></template>
    <template v-if="w.coordinator && ['Pending','Assigned'].includes(w.deliveryDetail.status)"><hr><label>Reason to cancel this delivery<textarea v-model="w.task.reason" :disabled="w.disabled" placeholder="Cancellation releases the reservation without consuming physical stock" /></label><button type="button" class="danger" :disabled="w.disabled || !w.task.reason.trim()" @click="w.cancelDelivery">Cancel delivery &amp; release reservation</button></template>
    <p v-if="w.deliveryDetail.status === 'Cancelled' && w.deliveryDetail.notes">Cancellation note: {{ w.deliveryDetail.notes }}</p>
    <p v-if="w.formError" class="form-error" role="alert">{{ w.formError }}</p>
  </WorkspaceModal>
</template>
